begin;
create table public.business_continuity_plans(id uuid primary key default gen_random_uuid(),plan_key text not null unique,name text not null,owner_user_id uuid not null references auth.users(id),rpo_minutes integer not null check(rpo_minutes between 1 and 10080),rto_minutes integer not null check(rto_minutes between 1 and 10080),database_backup_method text not null,storage_copy_method text not null,communications_pack text not null,active boolean not null default true,version integer not null default 1,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.backup_evidence(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.business_continuity_plans(id),backup_type text not null check(backup_type in('provider_database','logical_offsite','storage_offsite','continuity_pack')),backup_at timestamptz not null,location_reference text not null,checksum_or_provider_reference text not null,verified_by uuid not null references auth.users(id),verified_at timestamptz not null default now(),notes text,unique(plan_id,backup_type,backup_at));
create table public.restoration_drills(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.business_continuity_plans(id),started_at timestamptz not null,completed_at timestamptz not null check(completed_at>=started_at),restore_point_at timestamptz not null,recovered_database boolean not null,recovered_storage boolean not null,integrity_checks jsonb not null check(jsonb_typeof(integrity_checks)='object'),actual_rpo_minutes integer not null check(actual_rpo_minutes>=0),actual_rto_minutes integer not null check(actual_rto_minutes>=0),status text not null check(status in('passed','failed','partial')),evidence text not null,performed_by uuid not null references auth.users(id),created_at timestamptz not null default now());
alter table public.business_continuity_plans enable row level security;alter table public.backup_evidence enable row level security;alter table public.restoration_drills enable row level security;revoke all on public.business_continuity_plans,public.backup_evidence,public.restoration_drills from public,anon,authenticated;grant all on public.business_continuity_plans,public.backup_evidence,public.restoration_drills to service_role;
insert into public.business_continuity_plans(plan_key,name,owner_user_id,rpo_minutes,rto_minutes,database_backup_method,storage_copy_method,communications_pack,updated_by)select'kridiya-production','Kridiya production continuity',sr.user_id,1440,240,'Supabase provider daily backup plus governed off-site logical export.','Independent encrypted copy of customer and supplier document objects; database backup alone is insufficient.','Owner contacts, supplier/customer communication templates, DNS/platform access and restoration checklist.',sr.user_id from public.staff_roles sr join public.staff_profiles sp on sp.user_id=sr.user_id and sp.active where sr.role::text='owner'order by sr.created_at limit 1;
create function public.record_backup_evidence(p_plan_id uuid,p_type text,p_backup_at timestamptz,p_location text,p_reference text,p_notes text default null)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_id uuid;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;if p_type not in('provider_database','logical_offsite','storage_offsite','continuity_pack')or p_backup_at is null or p_backup_at>now()+interval'5 minutes'or char_length(btrim(coalesce(p_location,'')))<5 or char_length(btrim(coalesce(p_reference,'')))<8 then raise exception'Complete backup evidence is required';end if;insert into public.backup_evidence(plan_id,backup_type,backup_at,location_reference,checksum_or_provider_reference,verified_by,notes)values(p_plan_id,p_type,p_backup_at,btrim(p_location),btrim(p_reference),v_actor,nullif(btrim(coalesce(p_notes,'')),''))returning id into v_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'continuity.backup_verified','backup_evidence',v_id,jsonb_build_object('backup_type',p_type,'backup_at',p_backup_at));return v_id;end$$;
create function public.record_restoration_drill(p_plan_id uuid,p_started_at timestamptz,p_completed_at timestamptz,p_restore_point_at timestamptz,p_database boolean,p_storage boolean,p_checks jsonb,p_status text,p_evidence text)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_plan public.business_continuity_plans%rowtype;v_id uuid;v_rpo integer;v_rto integer;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;select*into v_plan from public.business_continuity_plans where id=p_plan_id and active;if not found then raise exception'Active continuity plan not found';end if;if p_completed_at<p_started_at or p_restore_point_at>p_started_at or jsonb_typeof(coalesce(p_checks,'null'))<>'object'or char_length(btrim(coalesce(p_evidence,'')))<20 then raise exception'Complete restoration evidence is required';end if;v_rpo:=ceil(extract(epoch from(p_started_at-p_restore_point_at))/60);v_rto:=ceil(extract(epoch from(p_completed_at-p_started_at))/60);if p_status='passed'and(not p_database or not p_storage or v_rpo>v_plan.rpo_minutes or v_rto>v_plan.rto_minutes or coalesce((p_checks->>'canonical_counts_match')::boolean,false)is not true)then raise exception'Passed drill must recover database and storage within objectives with integrity checks';end if;if p_status not in('passed','failed','partial')then raise exception'Invalid drill status';end if;insert into public.restoration_drills(plan_id,started_at,completed_at,restore_point_at,recovered_database,recovered_storage,integrity_checks,actual_rpo_minutes,actual_rto_minutes,status,evidence,performed_by)values(p_plan_id,p_started_at,p_completed_at,p_restore_point_at,p_database,p_storage,p_checks,v_rpo,v_rto,p_status,btrim(p_evidence),v_actor)returning id into v_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'continuity.restore_drill_recorded','restoration_drill',v_id,jsonb_build_object('status',p_status,'actual_rpo_minutes',v_rpo,'actual_rto_minutes',v_rto));return v_id;end$$;
create function public.get_business_continuity_readiness()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select case when public.is_admin()then coalesce(jsonb_agg(jsonb_build_object('plan',to_jsonb(p),'latest_backups',(select coalesce(jsonb_object_agg(x.backup_type,x.backup_at),'{}')from(select distinct on(backup_type)backup_type,backup_at from public.backup_evidence where plan_id=p.id order by backup_type,backup_at desc)x),'latest_drill',(select to_jsonb(d)from public.restoration_drills d where d.plan_id=p.id order by d.started_at desc limit 1),'ready',exists(select 1 from public.restoration_drills d where d.plan_id=p.id and d.status='passed'and d.started_at>now()-interval'180 days')and(select count(distinct backup_type)from public.backup_evidence b where b.plan_id=p.id and b.backup_at>now()-interval'35 days')=4)),'[]')else'[]'::jsonb end from public.business_continuity_plans p where p.active$$;
revoke execute on function public.record_backup_evidence(uuid,text,timestamptz,text,text,text),public.record_restoration_drill(uuid,timestamptz,timestamptz,timestamptz,boolean,boolean,jsonb,text,text),public.get_business_continuity_readiness()from public,anon;grant execute on function public.record_backup_evidence(uuid,text,timestamptz,text,text,text),public.record_restoration_drill(uuid,timestamptz,timestamptz,timestamptz,boolean,boolean,jsonb,text,text),public.get_business_continuity_readiness()to authenticated,service_role;
commit;
